@Component("tradeOrder-handler")
@ProcessingGroup("tradeOrder-processing-group")
public class TradeOrderEventHandler {
	
	// core constructor
	TradeOrderEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateTradeOrderEvent
     */
    @EventHandler
    public void handle( CreateTradeOrderEvent event) {
        entityManager.persist(new TradeOrder(event.getTradeOrderId(), event.getOrderId(), event.getQuantity(), event.getLimitPrice(), event.getPlacedAt(), event.getPortfolio(), event.getSecurity(), event.getTrades(), event.getSide(), event.getType(), event.getStatus(), event.getTimeInForce()));
    }

    /*
     * @param	event UpdateTradeOrderEvent
     */
    @EventHandler
    public TradeOrder handle( UpdateTradeOrderEvent event) {
    	entityManager.merge(new TradeOrder(event.getTradeOrderId(), event.getOrderId(), event.getQuantity(), event.getLimitPrice(), event.getPlacedAt(), event.getPortfolio(), event.getSecurity(), event.getTrades(), event.getSide(), event.getType(), event.getStatus(), event.getTimeInForce()));
    }
    
    /*
     * @param	event DeleteTradeOrderEvent
     */
    @EventHandler
    public void on( DeleteTradeOrderEvent event) {
    	TradeOrder entity = new TradeOrder();
   
    	// ------------------------------------------
    	// apply the TradeOrderId
    	// ------------------------------------------
    	entity.setTradeOrderId( event.getTradeOrderId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final TradeOrderRepository tradeOrderEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(TradeOrderEventHandler.class.getName());

}
